// Verify ADSolar webhook signature using shared secret
const crypto = require('crypto');
const payload = JSON.stringify($json.body ?? {});
const headers = $json.headers ?? {};
const provided = String(headers['x-adsolar-signature'] || headers['X-ADSolar-Signature'] || '').trim();
const secret = String($env.SHARED_SECRET || '');
let signatureValid = false;
if (secret && provided && payload) {
  const computed = crypto.createHmac('sha256', secret).update(payload).digest('hex');
  try {
    signatureValid = crypto.timingSafeEqual(Buffer.from(computed, 'utf8'), Buffer.from(provided.toLowerCase(), 'utf8'));
  } catch (error) {
    signatureValid = false;
  }
}
return [{ json: { body: $json.body ?? {}, headers, signatureValid } }];

// Parse AI normalization output and merge with original payload
const aiMessage = $json.message?.content ?? $json.message ?? '';
let parsed = {};
try {
  parsed = JSON.parse(aiMessage);
} catch (error) {
  parsed = { messages: [] };
}
const source = $node['Verify HMAC'].json;
return [{ json: {
  rawBody: source.body || {},
  headers: source.headers || {},
  conversationId: parsed.conversationId || source.body?.conversationId || '',
  clientName: parsed.clientName || source.body?.client?.name || '',
  clientEmail: parsed.clientEmail || source.body?.client?.email || '',
  clientAddress: parsed.clientAddress || source.body?.client?.address || '',
  typeInstallation: parsed.typeInstallation || source.body?.typeInstallation || '',
  devisUrl: parsed.devisUrl || source.body?.devisUrl || '',
  fichiers: parsed.fichiers || source.body?.fichiers || [],
  normalizedMessages: parsed.messages || [],
  aiSummary: parsed.summary || '',
  requestedActions: parsed.requestedActions || [],
  clientCompany: parsed.clientCompany || '',
  metadata: { normalization: aiMessage, receivedAt: new Date().toISOString() }
} }];

// Parse AI intent decision
const aiMessage = $json.message?.content ?? $json.message ?? '';
let parsed = {};
try {
  parsed = JSON.parse(aiMessage);
} catch (error) {
  parsed = { intent: 'help', confidence: 0 };
}
return [{ json: {
  ...$node['Adopt normalized context'].json,
  intent: parsed.intent || 'help',
  intentConfidence: parsed.confidence ?? 0,
  intentRationale: parsed.rationale || '',
  stageName: parsed.stageName || '',
  installationType: parsed.installationType || '',
  productName: parsed.productName || '',
  productQuantity: parsed.productQuantity || '',
  reminderDate: parsed.reminderDate || '',
  additionalNotes: parsed.additionalNotes || '',
  metadata: { ...$node['Adopt normalized context'].json.metadata, intentDecision: aiMessage }
} }];

// Prépare les propriétés Notion et le contexte email
const aiMessage = $json.message?.content ?? $json.message ?? '{}';
let parsed = {};
try { parsed = JSON.parse(aiMessage); } catch (error) { parsed = {}; }
const notionProperties = parsed.notionProperties || {};
const emailContext = parsed.emailContext || {};
const checklistKeywords = parsed.checklistKeywords || [];
return [{ json: {
  ...$node['Assemble intent context'].json,
  notionProperties,
  emailContext: {
    client: emailContext.client || $node['Assemble intent context'].json.clientName || 'Client ADSolar',
    typeInstallation: emailContext.typeInstallation || $node['Assemble intent context'].json.typeInstallation || 'Installation solaire',
    date: emailContext.date || new Date().toISOString().split('T')[0],
    devisUrl: emailContext.devisUrl || $node['Assemble intent context'].json.devisUrl || '',
    conversationId: emailContext.conversationId || $node['Assemble intent context'].json.conversationId || ''
  },
  checklistKeywords
} }];

// Prépare la requête Notion de création/mise à jour
const search = $json.data || $json.results || $json.notionSearch || $json;
const firstResult = Array.isArray(search?.results) ? search.results[0] : (Array.isArray(search) ? search[0] : undefined);
const properties = $node['Préparer données chantier'].json.notionProperties || {};
const databaseId = $env.NOTION_DB_ID;
let request = {};
if (firstResult && firstResult.id) {
  request = { method: 'PATCH', url: `https://api.notion.com/v1/pages/${firstResult.id}`, body: { properties } };
} else {
  request = { method: 'POST', url: 'https://api.notion.com/v1/pages', body: { parent: { database_id: databaseId }, properties } };
}
return [{ json: { ...$node['Préparer données chantier'].json, notionSearch: search, notionRequest: request, notionPageId: firstResult?.id || null } }];

// Lit le fichier materiel.csv et filtre selon le type d'installation
const fs = require('fs');
const path = require('path');
const context = $node['Préparer données chantier'].json;
const csvPath = path.join(process.cwd(), 'materiel.csv');
let rows = [];
try {
  const raw = fs.readFileSync(csvPath, 'utf8');
  const lines = raw.split(/?
/).filter(Boolean);
  const headers = lines.shift()?.split(',') || [];
  for (const line of lines) {
    const cols = line.split(',');
    const record = {};
    headers.forEach((header, idx) => { record[header.trim()] = (cols[idx] || '').trim(); });
    rows.push(record);
  }
} catch (error) {
  rows = [];
}
const normalizedType = (context.typeInstallation || context.emailContext?.typeInstallation || '').toLowerCase();
const filtered = rows.filter(row => (row.TypeInstallation || '').toLowerCase() === normalizedType);
const materialItems = filtered.map(row => ({ produit: row.Produit || '', quantite: row.Quantité || row.Quantite || '1' }));
return [{ json: { ...context, materialRows: rows, materialItems, materialType: context.typeInstallation || context.emailContext?.typeInstallation || '', notionProperties: context.notionProperties } }];

// Fusionne la sortie AI matériel avec les propriétés Notion
const aiMessage = $json.message?.content ?? $json.message ?? '{}';
let parsed = {};
try { parsed = JSON.parse(aiMessage); } catch (error) { parsed = {}; }
const materialText = parsed.materialText || ($node['Charger matériel'].json.materialItems || []).map(item => `${item.produit} x${item.quantite}`).join('\n') || 'À définir.';
const highlights = parsed.highlights || [];
const notionProperties = { ...$node['Charger matériel'].json.notionProperties };
notionProperties['Matériel à prévoir'] = { rich_text: [{ text: { content: materialText.slice(0, 2000) } }] };
return [{ json: { ...$node['Charger matériel'].json, notionProperties, materialText, materialHighlights: highlights } }];

// Prépare le contexte de mise à jour de statut
const aiMessage = $json.message?.content ?? $json.message ?? '{}';
let parsed = {};
try { parsed = JSON.parse(aiMessage); } catch (error) { parsed = {}; }
const stageName = parsed.stageName || $node['Assemble intent context'].json.stageName || 'En cours';
const reminderDays = parsed.reminderDays ?? ($node['Assemble intent context'].json.additionalNotes?.includes('rappel') ? 3 : null);
return [{ json: { ...$node['Assemble intent context'].json, stageName, reminderDays, emailSummary: parsed.emailSummary || '' } }];

// Compose les propriétés de statut à envoyer à Notion
const search = $json.data || $json.results || $json;
const firstResult = Array.isArray(search?.results) ? search.results[0] : undefined;
const properties = {
  'Statut': { select: { name: $node['Contexte statut'].json.stageName || 'En cours' } }
};
return [{ json: { ...$node['Contexte statut'].json, notionPageId: firstResult?.id || null, notionUpdateProperties: properties } }];

// Ajoute une ligne dans materiel.csv pour le nouveau type
const fs = require('fs');
const path = require('path');
const aiMessage = $json.message?.content ?? $json.message ?? '{}';
let parsed = {};
try { parsed = JSON.parse(aiMessage); } catch (error) { parsed = {}; }
const typeName = parsed.typeInstallation || 'Installation personnalisée';
const produits = Array.isArray(parsed.produits || parsed.products) ? parsed.produits || parsed.products : [];
const csvPath = path.join(process.cwd(), 'materiel.csv');
let lines = [];
try { lines = fs.readFileSync(csvPath, 'utf8').split(/?
/); } catch (error) { lines = ['TypeInstallation,Produit,Quantité']; }
const header = lines[0] || 'TypeInstallation,Produit,Quantité';
const records = produits.length ? produits : [{ name: 'Kit standard', quantity: '1' }];
for (const record of records) {
  const produit = record.name || record.produit || 'Produit';
  const quantity = record.quantity || record.quantite || '1';
  lines.push(`${typeName},${produit},${quantity}`);
}
fs.writeFileSync(csvPath, lines.filter(Boolean).join('
'));
return [{ json: { ...$node['Assemble intent context'].json, newInstallationType: typeName } }];

// Met à jour le fichier stock.csv avec le produit
const fs = require('fs');
const path = require('path');
const aiMessage = $json.message?.content ?? $json.message ?? '{}';
let parsed = {};
try { parsed = JSON.parse(aiMessage); } catch (error) { parsed = {}; }
const productName = parsed.productName || 'Produit';
const quantity = parsed.quantity || '0';
const supplier = parsed.supplier || 'Fournisseur';
const csvPath = path.join(process.cwd(), 'stock.csv');
let lines = [];
try { lines = fs.readFileSync(csvPath, 'utf8').split(/?
/); } catch (error) { lines = ['Produit,Quantité,Fournisseur']; }
const header = lines[0] || 'Produit,Quantité,Fournisseur';
const entries = lines.slice(1).filter(Boolean).map(line => line.split(','));
let updated = false;
for (let i = 0; i < entries.length; i++) {
  if ((entries[i][0] || '').toLowerCase() === productName.toLowerCase()) {
    entries[i] = [productName, String(quantity), supplier];
    updated = true;
  }
}
if (!updated) {
  entries.push([productName, String(quantity), supplier]);
}
const output = [header, ...entries.map(row => row.join(','))].join('
');
fs.writeFileSync(csvPath, output);
return [{ json: { ...$node['Assemble intent context'].json, productName, quantity, supplier } }];

// Agrège les matériels nécessaires depuis Notion
const notionData = $json.data || $json.results || $json;
const items = Array.isArray(notionData?.results) ? notionData.results : [];
const materials = {};
for (const page of items) {
  const materialProp = page.properties?.['Matériel à prévoir'];
  const text = materialProp?.rich_text?.map(t => t.plain_text || '').join('
') || '';
  const lines = text.split(/?
/).map(line => line.trim()).filter(Boolean);
  for (const line of lines) {
    const match = line.match(/^(.*) x(\d+)/i);
    if (match) {
      const name = match[1].trim();
      const qty = parseInt(match[2], 10) || 1;
      materials[name] = (materials[name] || 0) + qty;
    }
  }
}
const strategyNode = $node['Stratégie commande (AI)'].json || {};
const rawStrategy = strategyNode.message?.content ?? strategyNode.message ?? '{}';
let strategy = {};
try { strategy = JSON.parse(rawStrategy); } catch (error) { strategy = {}; }
const base = $node['Assemble intent context'].json || {};
return [{ json: { ...base, planningNotes: strategy.planningNotes || '', periode: strategy.periode || '', aggregatedMaterials: materials, strategyDetails: strategy } }];

// Compare le stock existant et calcule les manques
const fs = require('fs');
const path = require('path');
const stockPath = path.join(process.cwd(), 'stock.csv');
let stock = {};
try {
  const raw = fs.readFileSync(stockPath, 'utf8');
  const lines = raw.split(/?
/).filter(Boolean);
  lines.shift();
  for (const line of lines) {
    const [product, quantity] = line.split(',');
    stock[product.trim()] = parseInt(quantity, 10) || 0;
  }
} catch (error) {
  stock = {};
}
const materials = $json.aggregatedMaterials || {};
const shortages = [];
for (const [name, required] of Object.entries(materials)) {
  const available = stock[name] || 0;
  if (available < required) {
    shortages.push({ product: name, required, available, missing: required - available });
  }
}
return [{ json: { ...$json, stock, shortages } }];

// Construit un CSV à partir des manques
const shortages = $json.shortages || [];
let csv = 'Produit,Quantité manquante,Disponible,Requis';
for (const shortage of shortages) {
  csv += `
${shortage.product},${shortage.missing},${shortage.available},${shortage.required}`;
}
return [{ json: { ...$json, purchaseCsv: csv } }];

// Convertit le CSV texte en binaire pour l'envoi
const Buffer = require('buffer').Buffer;
const csvSource = $node['Préparer CSV'].json || {};
const csv = csvSource.purchaseCsv || $json.purchaseCsv || 'Produit,Quantité manquante,Disponible,Requis';
return [{ json: { ...csvSource, ...$json }, binary: { purchaseCsv: { data: Buffer.from(csv, 'utf8').toString('base64'), mimeType: 'text/csv' } } }];

// Signe la réponse avec HMAC SHA-256
const crypto = require('crypto');
const secret = String($env.SHARED_SECRET || '');
const body = JSON.stringify($json);
const signature = secret ? crypto.createHmac('sha256', secret).update(body).digest('hex') : '';
return [{ json: { body, signature } }];
